-- ============================================================================
-- V20: NORMALIZE PHONE SEED DATA
-- Goal: exactly 50 products, exactly 3 variants/product, 1 primary image/variant
-- Removes OPPO A78 to reduce the V19 total from 51 to 50 products.
-- Rebuilds variants so this migration does not depend on missing earlier seeds.
-- ============================================================================

START TRANSACTION;

CREATE TEMPORARY TABLE tmp_v20_phone_products (
    id BINARY(16) PRIMARY KEY
);


-- Remove images and variants for the 50 retained products before rebuilding.
DELETE pi
FROM product_images pi
JOIN product_variants pv ON pv.id = pi.variant_id
JOIN tmp_v20_phone_products tp ON tp.id = pv.product_id;

DELETE pv
FROM product_variants pv
JOIN tmp_v20_phone_products tp ON tp.id = pv.product_id;

-- Remove the 51st product introduced by V19.
DELETE pi
FROM product_images pi
JOIN product_variants pv ON pv.id = pi.variant_id
WHERE pv.product_id = UNHEX(REPLACE('33333333-3333-3333-3333-333333330041', '-', ''));

DELETE FROM product_variants
WHERE product_id = UNHEX(REPLACE('33333333-3333-3333-3333-333333330041', '-', ''));

DELETE FROM products
WHERE id = UNHEX(REPLACE('33333333-3333-3333-3333-333333330041', '-', ''));



DROP TEMPORARY TABLE tmp_v20_phone_products;

COMMIT;

-- Verification queries (expected: 50 products, 150 variants, 150 primary images)
SELECT COUNT(DISTINCT p.id) AS phone_count
FROM products p
JOIN product_variants pv ON pv.product_id = p.id
WHERE p.category_id = UNHEX(REPLACE('11111111-1111-1111-1111-111111111111', '-', ''));

