JOIN product_variants pv ON pv.id = pi.variant_id
WHERE pi.is_primary = TRUE
  AND pv.product_id IN (UNHEX(REPLACE('33333333-3333-3333-3333-333333330046', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333330045', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333330019', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333333303', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333330018', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333330017', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333333302', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333330016', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333330015', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333333301', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333333331', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333330014', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333330013', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333330012', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333330011', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333330047', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333330040', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333330036', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333333309', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333330037', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333330038', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333330039', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333333310', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333330043', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333330042', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333330027', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333330026', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333333306', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333330028', '-', '')), UNHEX(REPLACE('33333333-3333-3333-3333-333333330025', '-', '')), UNHEX(REPLACE('33333333-33